// === Tab: wfc.js ===
const DIRECTIONS = {
  UP: 0,
  RIGHT: 1,
  DOWN: 2,
  LEFT: 3
}

/**
 * Gets the opposite direction of the given side
 */
const opposite = (side) => {
  switch (side) {
    case DIRECTIONS.UP:
      return DIRECTIONS.DOWN
    case DIRECTIONS.RIGHT:
      return DIRECTIONS.LEFT
    case DIRECTIONS.DOWN:
      return DIRECTIONS.UP
    case DIRECTIONS.LEFT:
      return DIRECTIONS.RIGHT
  }
}
Array.prototype.sortUnique = function() {
  this.sort();
  var last_i;
  for (var i=0;i<this.length;i++)
      if ((last_i = this.lastIndexOf(this[i])) !== i)
          this.splice(i+1, last_i-i);
  return this;
}
class WFC {
  constructor ({ gridX, gridY, possibleTiles, debug }) {
    this.possibleTiles = possibleTiles
    this.debug = debug
    // this.lookupTable = this.initLookupTable()
    this.initializeState(gridX, gridY)
  }

  initializeState (gridX, gridY) {
    this.tiles = []
    this.gridX = gridX
    this.gridY = gridY
    for (let y = 0; y < gridY; y++) {
      for (let x = 0; x < gridX; x++) {
        this.tiles.push(new Tile({
          x,
          y,
          options: this.possibleTiles.slice(),
          debug: this.debug
        }))
      }
    }
  }

  generate () {
    // Find cells with lowest entropy
    let lowestEntropy = Infinity
    let lowestEntropyTiles = []
    let uncollapsedTiles = this.tiles.filter(t => !t.collapsed)
    if (uncollapsedTiles.length === 0) {
      return []
    }
    for (let tile of uncollapsedTiles) {
      if (tile.entropy < lowestEntropy) {
        lowestEntropy = tile.entropy
        lowestEntropyTiles = [tile]
      } else if (tile.entropy === lowestEntropy) {
        lowestEntropyTiles.push(tile)
      }
    }
    let tile = random(lowestEntropyTiles)
    tile.collapse()
    this.regenerateEntropy()
    return [tile]
  }

  regenerateEntropy() {
    for (let j = 0; j < this.gridY; j++) {
      for (let i = 0; i < this.gridX; i++) {
        let index = i + j * this.gridX
        let tile = this.tiles[index]
        if (tile.collapsed) {
          continue
        }
        let left = i > 0 ? this.tiles[index - 1] : null
        let right = i < this.gridX - 1 ? this.tiles[index + 1] : null
        let top = j > 0 ? this.tiles[index - this.gridX] : null
        let bottom = j < this.gridY - 1 ? this.tiles[index + this.gridX] : null
        if (left) {
          tile.options = this.filterValid(tile.options, left.options, DIRECTIONS.LEFT)
        }
        if (right) {
          tile.options = this.filterValid(tile.options, right.options, DIRECTIONS.RIGHT)
        }
        if (top) {
          tile.options = this.filterValid(tile.options, top.options, DIRECTIONS.UP)
        }
        if (bottom) {
          tile.options = this.filterValid(tile.options, bottom.options, DIRECTIONS.DOWN)
        }
        if (tile.options.length === 0) {
          // Deal with this issue later
          // Probably need to backtrack and try again
					if (this.debug) {			
						console.log('No options... fix later')
						console.log(`[${i}, ${j}]`)
						console.log({
							left: left ? left.options.map(o => o.adjacencies[1]).sortUnique() : null,
							right: right ? right.options.map(o => o.adjacencies[3]).sortUnique() : null,
							top: top ? top.options.map(o => o.adjacencies[2]).sortUnique() : null,
							bottom: bottom ? bottom.options.map(o => o.adjacencies[0]).sortUnique() : null
						})
					}
          throw new Error('Uncollapsable tile')
        }
      }
    }
  }

  filterValid (options, adjacentOptions, side) {
    // TODO: This could be done using a lookup table ??
    let valid = []
    for (let option of options) {
      for (let adjacentOption of adjacentOptions) {
        let d1 = option.adjacencies[side]
        let d2 = adjacentOption.adjacencies[opposite(side)]
        // Check if any direction is a list of possible directions, separated by |
        if (d1.includes('|')) {
          d1 = d1.split('|')
        } else {
          d1 = [d1]
        }
        if (d2.includes('|')) {
          d2 = d2.split('|')
        } else {
          d2 = [d2]
        }
        // if (d1 === d2) {
        if (d1.some(d => d2.includes(d))) {
          valid.push(option)
          break
        }
      }
    }
    return valid
  }

  seed (x, y, tile) {
    let index = x + y * this.gridX
    this.tiles[index].options = [tile]
    this.tiles[index].collapse()
    this.regenerateEntropy()
  }

  draw (w, h) {
    for (let tile of this.tiles) {
      tile.draw(w, h)
    }
  }

  shiftLeft () {
    // In each row, remove the first tile, shift the rest left, and add a new tile to the end
    for (let j = 0; j < this.gridY; j++) {
      let index = j * this.gridX
      for (let i = 0; i < this.gridX - 1; i++) {
        this.tiles[index + i] = this.tiles[index + i + 1]
        this.tiles[index + i].x = i
      }
      this.tiles[index + this.gridX - 1] = new Tile({
        x: this.gridX - 1,
        y: j,
        options: this.possibleTiles.slice(),
        debug: this.debug
      })
    }
  }

}

class Tile {
  constructor ({ x, y, options, debug }) {
    this.x = x
    this.y = y
    this.options = options
    this.collapsed = false
    this.debug = debug
  }

  get entropy () {
    return this.options.length
  }

  collapse () {
    this.collapsed = true
    // this.value = random(this.options)
    let totalWeight = this.options.reduce((acc, o) => acc + o.weight, 0)
    let r = random(totalWeight)
    let weight = 0
    for (let option of this.options) {
      weight += option.weight
      if (r < weight) {
        this.value = option
        break
      }
    }

    this.options = [this.value]
    if (this.onCollapse) {
      this.onCollapse(this)
    }
    if (this.debug) {
      console.log('Collapsing!', this.x, this.y, this.value.id || this.value.name)
    }
  }

  draw (w, h) {
    if (this.collapsed) {
      push()
      translate(this.x * w, this.y * h)
      this.value.draw(w, h, this)
      pop()

    }
    // Add debug text on top
    if (this.debug) {
      noFill()
      strokeWeight(2)
      stroke(this.collapsed ? 'green' : 'red')
      rect(this.x * w, this.y * h, w, h)
      strokeWeight(1)
      noFill()
      stroke(color(255, 0, 0, 50))
      textSize(10)
      text(`${this.x}, ${this.y}`, this.x * w + 10, this.y * h + 10)
      text('[' + this.options.map(o => o.id || o.name).join(' ') + ']', this.x * w + 10, this.y * h + 20)
    }
  }
}

const rotateDraw = (drawFunction, rotation) => {
  let newDraw = (w, h, tile) => {
    push()
    angleMode(DEGREES)
    // translate(x * w, y * h)
    switch(rotation % 4) {
      case 0:
        break
      case 1:
        translate(w, 0)
        break
      case 2:
        translate(w, h)
        break
      case 3:
        translate(0, h)
        break
    }
    rotate(rotation * 90)
    drawFunction(w, h, tile)
    pop()
  }
  return newDraw
}

const flipDraw = (drawFunction, mirrorX, mirrorY) => {
  let newDraw = (w, h, tile) => {
    push()
    if (mirrorX) {
      translate(w, 0)
      scale(-1, 1)
    }
    if (mirrorY) {
      translate(0, h)
      scale(1, -1)
    }
    drawFunction(w, h, tile)
    pop()
  }
  return newDraw
}

class TileDef {
  constructor ({ name, adjacencies, draw, weight, rotation, mirrorX, mirrorY }) {
    this.name = name
    // Check if adjacencies has 4, non falsy values
    if (adjacencies.length !== 4 || adjacencies.some(a => !a)) {
      throw new Error('Adjacencies must contain 4 valid values')
    }

    this.adjacencies = adjacencies
    this.draw = draw
    this.rotation = rotation || 0
    this.mirrorX = mirrorX || false
    this.mirrorY = mirrorY || false
    this.weight = weight || 1
  }

  clone () {
    return new TileDef({
      name: this.name,
      adjacencies: this.adjacencies.slice(),
      draw: this.draw,
      rotation: this.rotation,
      mirrorX: this.mirrorX,
      mirrorY: this.mirrorY,
      weight: this.weight
    })
  }

  static fromRotation (tile, { name, rotationStep, rotationFn = rotateType }) {
    if (rotationStep === 0) {
      return tile
    }
    let l = tile.adjacencies.length
    let n = rotationStep % l
    let rotatedAdjacencies
    if (rotationFn) {
      rotatedAdjacencies = rotationFn(tile.adjacencies, n)
    } else {
      rotatedAdjacencies = tile.adjacencies.slice(l - n).concat(tile.adjacencies.slice(0, l - n))
    }
    let newTileDef = new TileDef({
      name: name || `${tile.name}{${rotationStep}}`,
      adjacencies: rotatedAdjacencies,
      draw: rotateDraw(tile.draw, rotationStep),
      rotation: rotationStep // TODO: Calculate when original tile already has a rotation
    })
    return newTileDef
  }

  static fromMirror (tile, { name, mirrorX, mirrorY, mirrorFn = mirrorType }) {
    let flippedAdjacencies
    if (mirrorFn) {
      flippedAdjacencies = mirrorFn(tile.adjacencies, mirrorX, mirrorY)
    } else {
      flippedAdjacencies = tile.adjacencies.slice()
      if (mirrorY) {
        flippedAdjacencies[DIRECTIONS.UP] = tile.adjacencies[DIRECTIONS.DOWN]
        flippedAdjacencies[DIRECTIONS.DOWN] = tile.adjacencies[DIRECTIONS.UP]
      }
      if (mirrorX) {
        flippedAdjacencies[DIRECTIONS.LEFT] = tile.adjacencies[DIRECTIONS.RIGHT]
        flippedAdjacencies[DIRECTIONS.RIGHT] = tile.adjacencies[DIRECTIONS.LEFT]
      }
    }
    let newTileDef = new TileDef({
      name: name || `${tile.name}-${mirrorX ? 'X' : ''}${mirrorY ? 'Y' : ''}`,
      adjacencies: flippedAdjacencies,
      draw: flipDraw(tile.draw, mirrorX, mirrorY),
      rotation: tile.rotation,
      mirrorX: mirrorX,
      mirrorY: mirrorY
    })
    return newTileDef
  }
}

