const reverse = function (string) {
  return string.split('').reverse().join('')
}

const rotateType = (type, rotation) => {
  switch (rotation % 4) {
    case 0:
      return type
    case 1:
      return [reverse(type[3]), type[0], reverse(type[1]), type[2]]
    case 2:
      return [reverse(type[2]), reverse(type[3]), reverse(type[0]), reverse(type[1])]
    case 3:
      return [type[1], reverse(type[2]), type[3], reverse(type[0])]
  }
}

const mirrorType = (type, mirrorX, mirrorY) => {
  if (mirrorX && mirrorY) {
    return [ reverse(type[2]), reverse(type[3]), reverse(type[0]), reverse(type[1]) ]
  } else if (mirrorX) {
    return [ reverse(type[0]), type[3], reverse(type[2]), type[1]]
  } else if (mirrorY) {
    return [ type[2], reverse(type[1]), type[0], reverse(type[3])]
  } else {
    return type
  }
}

function getVariations (tiles, { rotations, mirrors } = {}) { // noprotect
  rotations = rotations || [0, 1, 2, 3]
  mirrors = mirrors || [{ mirrorY: true }]
  let variations = []
  for (let tile of tiles) {
    for (let rotation of rotations) {
      let rotatedTile = TileDef.fromRotation(tile, { rotationStep: rotation, rotationFn: rotateType })
      // console.log(rotatedTile.name)
      variations.push(rotatedTile)
      for (let mirror of mirrors) {
        let mirroredTile = TileDef.fromMirror(rotatedTile, {...mirror, mirrorFn: mirrorType })
        // console.log(mirroredTile.name)
        variations.push(mirroredTile)
      }
    }
  }
  return variations
}

