let drawBase = (w, h) => {
  noStroke()
  fill(BORDER_COLOR)
  rect(0, h - SURFACE_HEIGHT, w, SURFACE_HEIGHT)
}

let drawAngle = (w, h, x, y) => {
  let innerAngle = smoothLine(
    [
      [x - tw/2, 0],
      [x - tw/2, y - tw/2],
      [0, y - tw/2],
    ],
    tw,
  )
  let outerAngle = smoothLine(
    [
      [0, y + tw/2],
      [x + tw/2, y + tw/2],
      [x + tw/2, 0],
    ],
    tw*2
  )
  noStroke()
  fill(LIQUID_COLOR)
  beginShape()
  for (let p of [...innerAngle, ...outerAngle]) {
    vertex(...p)
  }
  endShape(CLOSE)

  strokeWeight(BORDER_WEIGHT)
  stroke(BORDER_COLOR)
  drawLineSegments(innerAngle)
  drawLineSegments(outerAngle)
}

let drawVTube = (w, h, x) => {
  noStroke()
