let drawSplitter = (w, h, x, y) => {
  noStroke()
  fill(LIQUID_COLOR)
  rect(x - tw/2, 0, tw, y)
  rect(0, y - tw/2, w, tw)
  strokeWeight(BORDER_WEIGHT)
  stroke(BORDER_COLOR)
  line(x - tw/2, 0, x - tw/2, y - tw/2)
  line(x + tw/2, 0, x + tw/2, y - tw/2)
  line(0, y - tw/2, x - tw/2, y - tw/2)
  line(x + tw/2, y - tw/2, w, y - tw/2)
  line(0, y + tw/2, w, y + tw/2)
}

// The points on the right line should be in reverse order for connecting with the left line
let drawCurvyTube = (left, right, radius) => {
  let l1 = smoothLine(left, radius, { includeEnds: false })
  let r1 = smoothLine(right, radius, { includeEnds: false })
  noStroke()
  fill(LIQUID_COLOR)

  let v = [left[0], ...l1, left[left.length - 1], right[0], ...r1, right[right.length - 1]]
  beginShape()
  for (let p of v) {
    vertex(...p)
  }
  endShape()

  strokeWeight(BORDER_WEIGHT)
  stroke(BORDER_COLOR)
  drawLineSegments([left[0], ...l1, left[left.length - 1]])
  drawLineSegments([right[0], ...r1, right[right.length - 1]])
}


