let _addSingleAdjacency = (adj1, adj2, direction) => {
  if (adj1 == 'E') {
    return adj2
  }
  if (adj2 == 'E') {
    return adj1
  }
  if ((adj1 == 'S' && adj2 == 'P') || (adj1 == 'P' && adj2 == 'S')) {
    return 'S'
  }
  throw new Error(`Invalid adjacency: ${adj1} ${adj2}`)
}

let _addAdjacency = (adj1, adj2) => {
  if (adj1.includes('|') || adj2.includes('|')) {
    throw new Error('Cannot add adjacency with | for now: ' + adj1 + ' ' + adj2)
  }

  if (adj1.length !== 3 || adj2.length !== 3) {
    throw new Error('Adjacency should have three letters: ' + adj1 + ' ' + adj2)
  }

  let result = ''
  for(let i = 0; i < 3; i++) {
    result = result + _addSingleAdjacency(adj1[i], adj2[i], i)
  }
  return result
}

function _withHTube (tileDef, heightIndex, drawTubeOnTop = false) {
  let adjacency = ['AEE', 'EAE', 'EEA'][heightIndex]

  let newTileDef = tileDef.clone()
  newTileDef.name = tileDef.name + ' with HTube(' + heightIndex + (drawTubeOnTop ? '▫' : '') + ')'
  newTileDef.adjacencies = [
    tileDef.adjacencies[0],
    _addAdjacency(tileDef.adjacencies[1], adjacency),
    tileDef.adjacencies[2],
    _addAdjacency(tileDef.adjacencies[3], adjacency),
  ]
  newTileDef.draw = (w, h, tile) => {
    let height = [w/4, w/2, w*3/4][heightIndex]
    if (drawTubeOnTop) {
      tileDef.draw(w, h, tile)
      drawHTube(w, h, height)
    } else {
      drawHTube(w, h, height)
      tileDef.draw(w, h, tile)
    }
  }
  return newTileDef
}

function _withAngle (tileDef, angleTopIndex, angleLeftIndex, drawTubeOnTop) {
  let adjacencyTop = ['AEE', 'EAE', 'EEA'][angleTopIndex]
  let adjacencyLeft = ['AEE', 'EAE', 'EEA'][angleLeftIndex]
  let newTileDef = tileDef.clone()
  newTileDef.name = tileDef.name + ' with Angle(' + angleTopIndex + ',' + angleLeftIndex + (drawTubeOnTop ? '▫' : '') + ')'
  newTileDef.adjacencies = [
    _addAdjacency(tileDef.adjacencies[0], adjacencyTop),
    tileDef.adjacencies[1],
    tileDef.adjacencies[2],
    _addAdjacency(tileDef.adjacencies[3], adjacencyLeft),
  ]
  newTileDef.draw = (w, h, tile) => {
    let width = [w/4, w/2, w*3/4][angleTopIndex]
    let height = [h/4, h/2, h*3/4][angleLeftIndex]
    if (drawTubeOnTop) {
      tileDef.draw(w, h, tile)
      drawAngle(w, h, width, height)
    } else {
      drawAngle(w, h, width, height)
      tileDef.draw(w, h, tile)
    }
  }
  return newTileDef
}

function _withVBeam (tileDef, beamIndex) {
  let adjacency = ['PEE', 'EPE', 'EEP'][beamIndex]
  let newTileDef = tileDef.clone()
  newTileDef.name = tileDef.name + ' with VBeam'
  newTileDef.adjacencies = [
    _addAdjacency(tileDef.adjacencies[0], adjacency),
    tileDef.adjacencies[1],
    _addAdjacency(tileDef.adjacencies[2], adjacency),
    tileDef.adjacencies[3],
  ],
  newTileDef.draw = (w, h, tile) => {
    let x = [w/4, w/2, w*3/4][beamIndex]
    drawVBeam(w, h, x, 0, h)
    tileDef.draw(w, h, tile)
  }
  return newTileDef
}

function _withSplitter (tileDef, splitterTopIndex, splitterSidesIndex) {
  let adjacencyTop = ['AEE', 'EAE', 'EEA'][splitterTopIndex]
  let adjacencySides = ['AEE', 'EAE', 'EEA'][splitterSidesIndex]
  let newTileDef = tileDef.clone()
  newTileDef.name = tileDef.name + ' with Splitter(' + splitterTopIndex + ',' + splitterSidesIndex + ')'
  newTileDef.adjacencies = [
    _addAdjacency(tileDef.adjacencies[0], adjacencyTop),
    _addAdjacency(tileDef.adjacencies[1], adjacencySides),
    tileDef.adjacencies[2],
    _addAdjacency(tileDef.adjacencies[3], adjacencySides),
  ]
  newTileDef.draw = (w, h, tile) => {
    let width = [w/4, w/2, w*3/4][splitterTopIndex]
    let height = [h/4, h/2, h*3/4][splitterSidesIndex]
    drawSplitter(w, h, width, height)
    tileDef.draw(w, h, tile)
  }
  return newTileDef
}

function _withMerger (tileDef, mergerTop1, mergerTop2, mergerBot) {
  let adjacencyTop = [
    mergerTop1 === 0 ? 'A' : 'E',
    (mergerTop1 === 1 || mergerTop2 === 1) ? 'A' : 'E',
    mergerTop2 === 2 ? 'A' : 'E',
  ].join('')
  let adjacencyBot = ['AEE', 'EAE', 'EEA'][mergerBot]
  let newTileDef = tileDef.clone()
  newTileDef.name = tileDef.name + ' with Merger(' + mergerTop1 + ',' + mergerTop2 + ',' + mergerBot + ')'
  newTileDef.adjacencies = [
    _addAdjacency(tileDef.adjacencies[0], adjacencyTop),
    tileDef.adjacencies[1],
    _addAdjacency(tileDef.adjacencies[2], adjacencyBot),
    tileDef.adjacencies[3],
  ]
  newTileDef.draw = (w, h, tile) => {
    let x1 = [w/4, w/2, w*3/4][mergerTop1]
    let x2 = [w/4, w/2, w*3/4][mergerTop2]
    let x3 = [w/4, w/2, w*3/4][mergerBot]
    let hy1 = mergerTop1 > mergerBot ? -tw/2 : tw/2
    let hy2 = mergerTop2 > mergerBot ? -tw/2 : tw/2
    let lineLeft = smoothLine([
      [x1 - tw/2, 0],
      [x1 - tw/2, h/2 + hy1],
      [x3 - tw/2, h/2 + hy1],
      [x3 - tw/2, h],
    ], tw, { includeEnds: true})
    let lineRight = smoothLine([
      [x2 + tw/2, 0],
      [x2 + tw/2, h/2 - hy2],
      [x3 + tw/2, h/2 - hy2],
      [x3 + tw/2, h],
    ].reverse(), tw, { includeEnds: true })

    let innerLine = smoothLine([
      [x1 + tw/2, 0],
      [x1 + tw/2, h/2 - tw/2],
      [x2 - tw/2, h/2 - tw/2],
      [x2 - tw/2, 0]
    ].reverse(), tw/2, { includeEnds: true })

    noStroke()
    fill(LIQUID_COLOR)

    beginShape()
    for (let p of [...lineLeft, ...lineRight, ...innerLine]) {
      vertex(...p)
    }
    endShape(CLOSE)

    strokeWeight(BORDER_WEIGHT)
    stroke(BORDER_COLOR)
    drawLineSegments(lineLeft)
    drawLineSegments(lineRight)
    drawLineSegments(innerLine)
  }
  return newTileDef
}

function _withGrip (tileDef, heldItemWidthPercentage, sideIndex, left) {
  let adjacencySide = ['PEE', 'EPE', 'EEP'][sideIndex]
  let newTileDef = tileDef.clone()
  newTileDef.name = tileDef.name + ' with Grip(' + (left ? 'L' : 'R') + ')'
  newTileDef.adjacencies = [
    tileDef.adjacencies[0],
    _addAdjacency(tileDef.adjacencies[1], left ? 'EEE' : adjacencySide),
    tileDef.adjacencies[2],
    _addAdjacency(tileDef.adjacencies[3], left ? adjacencySide : 'EEE'),
  ],
  newTileDef.draw = (w, h, tile) => {
    let gripY = [h/4, h/2, h*3/4][sideIndex]
    let tubeWidth = w * heldItemWidthPercentage
    drawHBeam(w, h, (left ? 0 : w/2), gripY, w/2)
    tileDef.draw(w, h, tile)
    // Grips
    fill(SUPPORT_COLOR1)
    let gripWidth = tw/2
    let gripHeight = tw*3/2
    rect(
      (w - tubeWidth) / 2 - gripWidth / 2,
      gripY - gripHeight / 2,
      gripWidth,
      gripHeight,
      gripWidth/2, 0, 0, gripWidth/2
    )
    rect(
      (w + tubeWidth) / 2 - gripWidth / 2,
      gripY - gripHeight / 2,
      gripWidth,
      gripHeight,
      0, gripWidth/2, gripWidth/2, 0
    )
  }
  return newTileDef
}

function _withBase (tileDef) {
  let newTileDef = tileDef.clone()
  newTileDef.name = tileDef.name + ' with Base'
  newTileDef.adjacencies = [
    tileDef.adjacencies[0],
    tileDef.adjacencies[1],
    _addAdjacency(tileDef.adjacencies[2], 'SSS'),
    tileDef.adjacencies[3],
  ]
  newTileDef.draw = (w, h, tile) => {
    tileDef.draw(w, h, tile)
    drawBase(w, h)
  }
  return newTileDef
}

function _withMixer (tileDef, indexTop, indexLeft) {
  let adjacencySides = ['AEE', 'EAE', 'EEA'][indexTop]
  let adjacencyTop = ['AEE', 'EAE', 'EEA'][indexLeft]
  let newTileDef = tileDef.clone()
  newTileDef.adjacencies = [
    _addAdjacency(tileDef.adjacencies[0], adjacencyTop),
    _addAdjacency(tileDef.adjacencies[1], adjacencySides),
    tileDef.adjacencies[2],
    _addAdjacency(tileDef.adjacencies[3], adjacencySides)
  ]
  newTileDef.draw = (w, h, tile) => {
    let y = [h/4, h/2, h*3/4][indexTop]
    let x = [w/4, w/2, w*3/4][indexLeft]
    let outerRadius = h/3, innerRadius = 5*h/24
    drawSplitter(w, h, x, y)
    strokeWeight(BORDER_WEIGHT)
    stroke(BORDER_COLOR)
    fill(GLASS_COLOR)
    circle(x, y, outerRadius)
    fill(AIR_COLOR)
    circle(x, y, innerRadius)
    tile._color = tile._color || color(random(255), random(255), random(255))
    tile._full = tile._full || random(0, 45)
    fill(tile._color)
    switch(tile.value.rotation) {
      case 0:
        arc(x, y, innerRadius, innerRadius, -tile._full, 180 + tile._full, CHORD)
        break
      case 1: // Rotated 90 degrees clockwise
        arc(x, y, innerRadius, innerRadius, -90 -tile._full, 90 + tile._full, CHORD)
        break
      case 2: // Rotated 180 degrees clockwise
        arc(x, y, innerRadius, innerRadius, 180 - tile._full, 360 + tile._full, CHORD)
        break
      case 3: // Rotated 270 degrees clockwise
        arc(x, y, innerRadius, innerRadius, 90 - tile._full, 270 + tile._full, CHORD)
        break
    }
  }
  return newTileDef
}

function _withUnion (tileDef, indexTop, indexSide) {
  let adjacencyTop = ['PEE', 'EPE', 'EEP'][indexTop]
  let adjacencySide = ['PEE', 'EPE', 'EEP'][indexSide]
  let newTileDef = tileDef.clone()
  newTileDef.name = tileDef.name + ' with union(' + indexTop + ', ' + indexSide + ')'
  newTileDef.adjacencies = [
    _addAdjacency(tileDef.adjacencies[0], adjacencyTop),
    tileDef.adjacencies[1],
    _addAdjacency(tileDef.adjacencies[2], adjacencyTop),
    _addAdjacency(tileDef.adjacencies[3], adjacencySide)
  ]
  newTileDef.draw = (w, h, tile) => {
    tileDef.draw(w, h)

    let x = [w/4, w/2, w*3/4][indexTop]
    let y = [h/4, h/2, h*3/4][indexSide]
    let unionWidth = tw*3/2
    let unionHeight = tw*3

    drawVBeam(w, h, x, 0, h)
    drawHBeam(w, h, 0, y, x + tw/2)

    stroke(BORDER_COLOR)
    strokeWeight(BORDER_WEIGHT)
    fill(SUPPORT_COLOR1)
    rect(x - unionWidth/2, y - unionHeight/2, unionWidth, unionHeight, tw/4)
  }
  return newTileDef
}


