    vertex(baseX2, baseY)
    vertex(px2, baseY - height)
    vertex(px1, baseY - height)
    vertex(baseX1, baseY)
    cx = w/3
    cy = 3*h/4
    r = w/8
    angle = 180
    angleEnd = 90
    angleStep = 4
    let _wG_3 = 0; while ((angle > angleEnd) && ++_wG_3 < 20000) {
